INSERT INTO `xiaji_document_analyses` VALUES ('ing-47ab9e5db0bf4b1d','deepseek-ai/DeepSeek-R1-0528-Qwen3-8B','一名神秘刺客在夜色中行动，腰间横刀透出杀意，暗器链子暗示其专业技能，整体氛围紧张危险。','{\"summary\": \"一名神秘刺客在夜色中行动，腰间横刀透出杀意，暗器链子暗示其专业技能，整体氛围紧张危险。\", \"characters\": [{\"name\": \"刺客\", \"aliases\": [], \"role\": \"反派/刺客\", \"is_main\": true, \"gender\": \"男\", \"age_group\": \"youth\", \"body_type\": \"精悍\", \"description\": \"身手敏捷，气质阴冷，常年习武，指节厚茧，面露凶相。\", \"face_prompt\": \"男性，青年，黑色短发，黑色眼眸，苍白肤色，棱角分明\"}], \"scenes\": [], \"props\": [{\"name\": \"刀\", \"aliases\": [\"腰刀\"], \"prop_type\": \"weapon\", \"visual_prompt\": \"一柄缠绕浸血旧布的长刀，刀柄厚实，刀身寒光凛冽，材质为钢铁，尺寸中等，色泽暗沉，刀刃刻有不明纹饰。\", \"owner\": \"刺客\"}, {\"name\": \"暗器链子\", \"aliases\": [], \"prop_type\": \"weapon\", \"visual_prompt\": \"一串小巧金属暗器悬于袖中，材质为青铜，色泽暗哑，饰有简单花纹，长度适中，整体造型简洁锋利。\", \"owner\": \"刺客\"}, {\"name\": \"旧布\", \"aliases\": [\"浸血旧布\"], \"prop_type\": \"accessory\", \"visual_prompt\": \"一块略显陈旧的布料，质地粗糙，浸染暗红色痕迹，边缘磨损，尺寸不规则，颜色深褐，无明显装饰。\", \"owner\": \"刺客\"}], \"episodes\": [{\"number\": 1, \"title\": \"夜影潜行\", \"content_summary\": \"第一人称视角下，刺客在夜色中行动，展现其冷酷身手与致命武器，营造紧张氛围。\", \"main_conflict\": \"刺客的行动与潜在目标之间的对抗。\", \"cliffhanger\": \"黑巾下的面容究竟为何？他的下一个目标是谁？\", \"key_events\": [\"刺客穿着夜行衣在夜色中行动，足蹬软靴无声移动。\", \"腰间刀鞘透出杀意，袖中暗器链子晃动。\", \"低头时黑巾下颚绷紧，暗示凶狠性格。\", \"刀柄缠绕浸血旧布，显示多次使用与血腥经历。\"]}], \"model\": \"deepseek-ai/DeepSeek-R1-0528-Qwen3-8B\", \"target_episodes\": 1, \"ingest_settings\": {\"spine_template\": \"drama\", \"visual_style\": \"chinese_period_drama\", \"narration_style\": \"first_person\", \"ethnicity\": \"Chinese\"}}','[\"解析原文：143 字\", \"规则识别章节：1 章\", \"调用已配置大模型分析角色、场景、道具和剧集规划\", \"分析完成：1 个角色，0 个场景，3 个道具，1 集规划\", \"已转入资产库：1 个角色，0 个场景，3 个道具\"]','2026-09-02T08:02:55.798869+00:00','2026-09-02T08:02:55.798869+00:00'),('ing-67eb9bddd5654c1b','deepseek-ai/DeepSeek-R1-0528-Qwen3-8B','骊珠洞天面临崩塌，齐静春为保护百姓殉道，留下遗愿。陈平安作为第一人称叙述者，护送少女李宝瓶南下求学，经历生死搏杀黑白双蟒，借助《撼山谱》从废人进阶至水银境。','{\"summary\": \"骊珠洞天面临崩塌，齐静春为保护百姓殉道，留下遗愿。陈平安作为第一人称叙述者，护送少女李宝瓶南下求学，经历生死搏杀黑白双蟒，借助《撼山谱》从废人进阶至水银境。\", \"characters\": [{\"name\": \"陈平安\", \"aliases\": [], \"role\": \"主角\", \"is_main\": true, \"gender\": \"男\", \"age_group\": \"youth\", \"body_type\": \"\", \"description\": \"\", \"face_prompt\": \"男性，youth，黑色短发，蓝色眼睛，普通肤色，圆脸\"}, {\"name\": \"李宝瓶\", \"aliases\": [], \"role\": \"被护少女\", \"is_main\": false, \"gender\": \"女\", \"age_group\": \"youth\", \"body_type\": \"\", \"description\": \"\", \"face_prompt\": \"女性，youth，黑色长发，黑色眼睛，小麦肤色，瓜子脸\"}, {\"name\": \"齐静春\", \"aliases\": [], \"role\": \"守护者\", \"is_main\": false, \"gender\": \"男\", \"age_group\": \"middle\", \"body_type\": \"\", \"description\": \"\", \"face_prompt\": \"男性，middle，黑色短发，灰色眼睛，中等肤色，方脸\"}], \"scenes\": [{\"name\": \"骊珠洞天\", \"scene_type\": \"exterior\", \"description\": \"一个即将崩塌的神秘洞天，周围是小镇和百姓，环境险峻，危机四伏。\"}, {\"name\": \"落魄山\", \"scene_type\": \"exterior\", \"description\": \"隐于市的山林，止境武夫所在，环境幽静，武道气息浓厚。\"}], \"props\": [{\"name\": \"《撼山谱》\", \"aliases\": [], \"prop_type\": \"artifact\", \"visual_prompt\": \"一本古籍，材质纸张，工艺手抄，尺寸中等，色泽古旧，纹饰无特殊。\", \"owner\": \"陈平安\"}], \"episodes\": [{\"number\": 1, \"title\": \"少年武道崛起\", \"content_summary\": \"陈平安护送李宝瓶南下，对抗黑白双蟒，使用《撼山谱》进阶武境，成就水银境。\", \"main_conflict\": \"保护李宝瓶安全抵达目的地，同时对抗黑白双蟒和提升自身武力。\", \"cliffhanger\": \"陈平安在落魄山悟拳后，境界大增，但前方危机重重。\", \"key_events\": [\"齐静春殉道留下遗愿\", \"陈平安护送李宝瓶\", \"搏杀黑白双蟒\", \"使用《撼山谱》续命\", \"入木胎境\", \"遇到崔诚，悟拳，成就水银境\"]}], \"model\": \"deepseek-ai/DeepSeek-R1-0528-Qwen3-8B\", \"target_episodes\": 1, \"ingest_settings\": {\"spine_template\": \"drama\", \"visual_style\": \"anime\", \"narration_style\": \"first_person\", \"ethnicity\": \"Chinese\"}}','[\"解析原文：169 字\", \"规则识别章节：1 章\", \"调用已配置大模型分析角色、场景、道具和剧集规划\", \"分析完成：3 个角色，2 个场景，1 个道具，1 集规划\", \"已转入资产库：3 个角色，2 个场景，1 个道具\"]','2026-09-04T02:42:14.272144+00:00','2026-09-04T02:42:14.272144+00:00'),('ing-8d8195100af0435d','deepseek-ai/DeepSeek-R1-0528-Qwen3-8B','本片讲述一艘豪华邮轮在平静的大海航行时遭遇突如其来的海啸，导致船只沉没，幸存者在海边和山洞中挣扎求生的故事。','{\"summary\": \"本片讲述一艘豪华邮轮在平静的大海航行时遭遇突如其来的海啸，导致船只沉没，幸存者在海边和山洞中挣扎求生的故事。\", \"characters\": [{\"name\": \"荣哥\", \"aliases\": [], \"role\": \"男主角\", \"is_main\": true, \"gender\": \"男\", \"age_group\": \"youth\", \"body_type\": \"中等偏健壮\", \"description\": \"性格沉稳，面对灾难时冷静应对。外貌：短黑发，浓密眉毛，身材中等偏健壮，眼神坚定。他抱着一个纸箱，里面装有生活物资，帮助自己和他人度过难关。\", \"face_prompt\": \"男性，青年，短黑发，浓密眉毛，深邃眼神\"}], \"scenes\": [{\"name\": \"平静的大海\", \"scene_type\": \"exterior\", \"description\": \"广阔的海洋，晴朗的天空，邮轮在海面上缓慢航行，甲板上有游客，周围环境宁静，光线明亮，海面微波粼粼。\"}, {\"name\": \"邮轮甲板\", \"scene_type\": \"exterior\", \"description\": \"邮轮甲板，阳光明亮，海面远延伸，周围有游客和救生设施，栏杆、桌椅等陈设可见，光线充足，海风轻拂。\"}, {\"name\": \"海啸袭来\", \"scene_type\": \"exterior\", \"description\": \"邮轮甲板，海水迅速上涨，巨浪翻涌，船体剧烈摇晃，周围有散落的救生设备，光线昏暗，海浪声巨大。\"}, {\"name\": \"邮轮沉没\", \"scene_type\": \"exterior\", \"description\": \"邮轮逐渐倾斜，周围漂浮着救生圈和行李，海浪拍打，天空阴沉，光线逐渐变暗，环境压抑。\"}, {\"name\": \"海边的幸存者\", \"scene_type\": \"exterior\", \"description\": \"偏僻海岸，天空阴沉，海浪拍打沙滩，散落的木板和救生圈，沙滩湿润，环境荒凉，光线阴暗。\"}, {\"name\": \"山洞\", \"scene_type\": \"interior\", \"description\": \"天然山洞，内部干燥，角落堆放大量物资，如矿泉水、罐头等，洞内有简易躺椅，光线由露营灯提供，环境相对安全。\"}, {\"name\": \"山洞内部\", \"scene_type\": \"interior\", \"description\": \"山洞内部，物资整齐堆放，有小型露营灯照明，洞内有简易躺椅，环境整洁，光线柔和。\"}], \"props\": [{\"name\": \"纸箱\", \"aliases\": [\"棕色纸箱\"], \"prop_type\": \"accessory\", \"visual_prompt\": \"棕色纸箱，材质为硬纸板，表面有轻微磨损，尺寸中等，内部装有生活物资，如食物和水，整体外观朴素实用。\", \"owner\": \"荣哥\"}], \"episodes\": [{\"number\": 1, \"title\": \"平静的开始\", \"content_summary\": \"一艘豪华邮轮在平静的大海航行，气氛轻松愉快，游客们在甲板上散步、拍照。\", \"main_conflict\": \"无明显冲突，气氛平静。\", \"cliffhanger\": \"旁白暗示平静的大海即将变成噩梦。\", \"key_events\": [\"邮轮航行，游客在甲板活动\", \"旁白预告灾难\"]}, {\"number\": 2, \"title\": \"荣哥的物资\", \"content_summary\": \"荣哥抱着纸盒子在甲板上行走，里面装有生活物资。\", \"main_conflict\": \"无明显冲突，荣哥观察周围环境。\", \"cliffhanger\": \"荣哥保持警惕，但周围游客无异常。\", \"key_events\": [\"荣哥抱着纸盒子行走\", \"游客正常活动\"]}, {\"number\": 3, \"title\": \"海啸来袭\", \"content_summary\": \"海啸突然袭来，邮轮甲板被淹没，游客惊慌失措。\", \"main_conflict\": \"海啸突袭，邮轮面临沉没危机。\", \"cliffhanger\": \"荣哥惊恐地面对突如其来的灾难。\", \"key_events\": [\"海啸出现，巨浪冲向邮轮\", \"游客逃命，荣哥抱紧物资\"]}, {\"number\": 4, \"title\": \"逃亡与沉没\", \"content_summary\": \"邮轮剧烈摇晃，部分乘客被卷入海中，船只逐渐沉入海底。\", \"main_conflict\": \"生存危机，乘客们在混乱中逃命。\", \"cliffhanger\": \"邮轮沉入海底，幸存者被海浪卷走。\", \"key_events\": [\"游客逃命，荣哥抱紧纸箱\", \"邮轮倾斜，部分乘客被卷入海中\"]}, {\"number\": 5, \"title\": \"海边的幸存者\", \"content_summary\": \"幸存者爬上岸，浑身湿透，疲惫不堪，荣哥仍紧抱着物资。\", \"main_conflict\": \"幸存者在海边寻找生存机会。\", \"cliffhanger\": \"荣哥抬头望向大海，未知的命运。\", \"key_events\": [\"幸存者爬上岸，互相搀扶\", \"荣哥抱着物资，望向大海\"]}, {\"number\": 6, \"title\": \"山洞中的希望\", \"content_summary\": \"幸存者进入山洞，整理物资，准备暂时生存。\", \"main_conflict\": \"寻找安全的临时栖身之所。\", \"cliffhanger\": \"荣哥露出一丝轻松的笑容，但危机仍未解除。\", \"key_events\": [\"进入山洞，整理物资\", \"荣哥露出笑容，但危机仍未解除\"]}, {\"number\": 7, \"title\": \"短暂的休息\", \"content_summary\": \"幸存者在山洞中休息，物资充足，暂时安全。\", \"main_conflict\": \"短暂的平静，但灾难仍未结束。\", \"cliffhanger\": \"荣哥闭上眼睛休息，但外面是漆黑的大海。\", \"key_events\": [\"荣哥休息，物资充足\", \"镜头拉远，山洞外是漆黑的大海\"]}, {\"number\": 8, \"title\": \"未知的未来\", \"content_summary\": \"幸存者在山洞中休息，但灾难仍未结束，未来充满未知。\", \"main_conflict\": \"生存与未知的命运。\", \"cliffhanger\": \"镜头拉远，山洞外是漆黑的大海和不断翻涌的海浪。\", \"key_events\": [\"幸存者休息，但灾难仍未结束\", \"镜头拉远，山洞外是漆黑的大海\"]}], \"model\": \"deepseek-ai/DeepSeek-R1-0528-Qwen3-8B\", \"target_episodes\": 8, \"ingest_settings\": {\"spine_template\": \"drama\", \"art_style_id\": \"as_1008\", \"visual_style\": \"as_1008\", \"narration_style\": \"first_person\", \"ethnicity\": \"Chinese\"}}','[\"解析原文：2480 字\", \"规则识别章节：8 章\", \"调用已配置大模型分析角色、场景、道具和剧集规划\", \"分析完成：1 个角色，7 个场景，1 个道具，8 集规划\", \"已转入资产库：1 个角色，7 个场景，1 个道具\"]','2026-09-08T01:57:56.137698+00:00','2026-09-08T01:57:56.137698+00:00'),('ing-b27071e23e464d01','deepseek-ai/DeepSeek-R1-0528-Qwen3-8B','骊珠洞天即将崩塌，齐静春为保护百姓殉道身陨，留下机缘与遗愿。陈平安护送少女李宝瓶南下求学，一路与黑白双蟒搏斗，凭借《撼山谱》和六步走桩续命，从废人境突破至泥胚境，后入木胎境，最终成就水银境。','{\"summary\": \"骊珠洞天即将崩塌，齐静春为保护百姓殉道身陨，留下机缘与遗愿。陈平安护送少女李宝瓶南下求学，一路与黑白双蟒搏斗，凭借《撼山谱》和六步走桩续命，从废人境突破至泥胚境，后入木胎境，最终成就水银境。\", \"characters\": [{\"name\": \"齐静春\", \"aliases\": [], \"role\": \"守护者\", \"is_main\": false, \"gender\": \"男\", \"age_group\": \"middle\", \"body_type\": \"中等身材，略显清瘦\", \"description\": \"为保护百姓而牺牲的武者，心怀正义，武力高强。\", \"face_prompt\": \"男性，中年，黑色短发，深邃丹凤眼，小麦肤色，方正脸型\"}, {\"name\": \"陈平安\", \"aliases\": [], \"role\": \"主角\", \"is_main\": true, \"gender\": \"男\", \"age_group\": \"youth\", \"body_type\": \"健壮魁梧\", \"description\": \"从废人境起步，通过不懈努力突破至武夫境界，性格坚韧不拔。\", \"face_prompt\": \"男性，二十多岁，黑色短发，明亮有神的眼睛，小麦肤色，棱角分明的脸型\"}, {\"name\": \"李宝瓶\", \"aliases\": [], \"role\": \"同伴\", \"is_main\": false, \"gender\": \"女\", \"age_group\": \"child\", \"body_type\": \"娇小玲珑\", \"description\": \"被陈平安护送的少女，性格活泼，求学心切。\", \"face_prompt\": \"女性，十多岁，黑色长发，大而明亮的眼睛，白皙肤色，圆润的脸型\"}, {\"name\": \"崔诚\", \"aliases\": [], \"role\": \"导师\", \"is_main\": false, \"gender\": \"男\", \"age_group\": \"middle\", \"body_type\": \"中等身材，体格健壮\", \"description\": \"隐居的止境武夫，性格隐忍，教导陈平安悟拳。\", \"face_prompt\": \"男性，四十多岁，黑色短发，锐利的眼神，小麦肤色，方下巴\"}], \"scenes\": [{\"name\": \"骊珠洞天\", \"scene_type\": \"interior\", \"description\": \"古老的洞天福地，灵气充沛，洞内有古老的阵法和建筑，即将崩塌。\"}, {\"name\": \"落魄山\", \"scene_type\": \"exterior\", \"description\": \"山势险峻，云雾缭绕，是陈平安的家乡，也是他修炼的地方。\"}, {\"name\": \"南行之路\", \"scene_type\": \"exterior\", \"description\": \"崎岖的山路，风景秀丽但危机四伏，陈平安与李宝瓶一路南下。\"}], \"props\": [{\"name\": \"《撼山谱》\", \"aliases\": [], \"prop_type\": \"document\", \"visual_prompt\": \"一本古旧的书籍，封面为深蓝色，书页泛黄，上面有复杂的武学图谱，材质为兽皮，边缘磨损。\", \"owner\": \"陈平安\"}, {\"name\": \"止境玉佩\", \"aliases\": [], \"prop_type\": \"accessory\", \"visual_prompt\": \"一枚玉质令牌，形状如圆形，表面刻有复杂的纹路，颜色青翠，触手温润，边缘光滑。\", \"owner\": \"崔诚\"}], \"episodes\": [{\"number\": 1, \"title\": \"崩塌前的守护\", \"content_summary\": \"齐静春为保护骊珠洞天百姓而牺牲，陈平安踏上南下求学之路。\", \"main_conflict\": \"骊珠洞天即将崩塌，齐静春选择殉道。\", \"cliffhanger\": \"陈平安背负着齐静春的遗愿，踏上未知的旅程。\", \"key_events\": [\"齐静春为保护百姓牺牲\", \"陈平安护送李宝瓶南下\", \"陈平安与黑白双蟒搏斗\", \"陈平安突破至泥胚境\"]}], \"model\": \"deepseek-ai/DeepSeek-R1-0528-Qwen3-8B\", \"target_episodes\": 1, \"ingest_settings\": {\"spine_template\": \"drama\", \"visual_style\": \"chinese_period_drama\", \"narration_style\": \"first_person\", \"ethnicity\": \"Chinese\"}}','[\"解析原文：169 字\", \"规则识别章节：1 章\", \"调用已配置大模型分析角色、场景、道具和剧集规划\", \"分析完成：4 个角色，3 个场景，2 个道具，1 集规划\", \"已转入资产库：4 个角色，3 个场景，2 个道具\"]','2026-09-03T00:55:42.157209+00:00','2026-09-03T00:55:42.157209+00:00'),('ing-ba5b0f7b61ea489e','deepseek-ai/DeepSeek-R1-0528-Qwen3-8B','孤儿主角因意外打碎本命瓷而失去修行机会，但在镇上遇到两位修行者，被约定练功百万次后收为徒弟。','{\"summary\": \"孤儿主角因意外打碎本命瓷而失去修行机会，但在镇上遇到两位修行者，被约定练功百万次后收为徒弟。\", \"characters\": [{\"name\": \"主角\", \"aliases\": [\"小哑巴\"], \"role\": \"孤儿\", \"is_main\": true, \"gender\": \"男\", \"age_group\": \"child\", \"body_type\": \"瘦弱\", \"description\": \"命运多舛的孤儿，失去修行机会后生活困苦，性格坚韧。\", \"face_prompt\": \"男性，儿童，短发黑，小眼睛，苍白肤色，瘦削脸型\"}, {\"name\": \"齐静春\", \"aliases\": [], \"role\": \"文圣弟子\", \"is_main\": false, \"gender\": \"男\", \"age_group\": \"middle\", \"body_type\": \"魁梧\", \"description\": \"暗中保护主角的修行者，性格温和，实力深厚。\", \"face_prompt\": \"男性，中年，黑色短发，深邃眼睛，小麦肤色，方脸\"}, {\"name\": \"宁姚\", \"aliases\": [], \"role\": \"剑修少女\", \"is_main\": false, \"gender\": \"女\", \"age_group\": \"youth\", \"body_type\": \"娇小\", \"description\": \"冷傲的剑修，与主角有约定，性格外冷内热。\", \"face_prompt\": \"女性，青年，黑色长发，冷冽眼睛，白皙肤色，瓜子脸\"}], \"scenes\": [{\"name\": \"泥瓶巷\", \"scene_type\": \"exterior\", \"description\": \"泥瓶巷是骊珠洞天中的一个贫民窟，房屋破旧，街道泥泞，孤儿主角在这里生活。\"}, {\"name\": \"长生桥\", \"scene_type\": \"nature\", \"description\": \"长生桥是骊珠洞天中的一个神秘地点，传说与修行有关，是主角命运转折的关键之地。\"}], \"props\": [{\"name\": \"本命瓷\", \"aliases\": [], \"prop_type\": \"artifact\", \"visual_prompt\": \"一件脆弱的瓷器，通体透明，内里有流转的光芒，象征着修行天赋。\", \"owner\": \"主角\"}, {\"name\": \"长生桥\", \"aliases\": [], \"prop_type\": \"artifact\", \"visual_prompt\": \"一座古老的石桥，横跨在深渊之上，桥身刻有神秘符文，散发着淡淡的光芒。\", \"owner\": \"\"}], \"episodes\": [{\"number\": 1, \"title\": \"命运的转折\", \"content_summary\": \"孤儿主角在泥瓶巷失去本命瓷，命运似乎已定，但镇上却有两位修行者出现，改变了他的命运。\", \"main_conflict\": \"主角因打碎本命瓷而失去修行机会，生活陷入困境。\", \"cliffhanger\": \"主角与宁姚约定练功百万次，究竟何时才能实现这个目标？\", \"key_events\": [\"主角五岁那年打碎本命瓷，长生桥断裂。\", \"齐静春和宁姚出现，决定保护主角。\", \"主角与宁姚立下约定，练功百万次后收徒。\"]}], \"model\": \"deepseek-ai/DeepSeek-R1-0528-Qwen3-8B\", \"target_episodes\": 1, \"ingest_settings\": {\"spine_template\": \"drama\", \"visual_style\": \"chinese_period_drama\", \"narration_style\": \"first_person\", \"ethnicity\": \"Chinese\"}}','[\"解析原文：116 字\", \"规则识别章节：1 章\", \"调用已配置大模型分析角色、场景、道具和剧集规划\", \"分析完成：3 个角色，2 个场景，2 个道具，1 集规划\"]','2026-09-01T03:14:51.214639+00:00','2026-09-01T03:14:51.214639+00:00'),('ing-cce47fdd1d514e76','deepseek-ai/DeepSeek-R1-0528-Qwen3-8B','末日废墟中，一名幸存者在地下室遭遇变异怪物，面临生存抉择。','{\"summary\": \"末日废墟中，一名幸存者在地下室遭遇变异怪物，面临生存抉择。\", \"characters\": [{\"name\": \"男主\", \"aliases\": [\"幸存者\", \"叔叔\"], \"role\": \"第一人称叙述者\", \"is_main\": true, \"gender\": \"男\", \"age_group\": \"youth\", \"body_type\": \"健壮但偏瘦\", \"description\": \"冷静坚韧，面对困境不慌不忙。外貌：短黑发，脸上有灰尘和轻微伤口，身材偏瘦但有力。气质：略显疲惫但眼神坚定，给人一种沧桑感。\", \"face_prompt\": \"男性，青年，短黑发，有伤口的脸，深邃的眼神，略显疲惫\"}, {\"name\": \"小女孩\", \"aliases\": [\"小女孩\"], \"role\": \"需要帮助的角色\", \"is_main\": false, \"gender\": \"女\", \"age_group\": \"child\", \"body_type\": \"娇小虚弱\", \"description\": \"8岁，虚弱无力，但眼神中透露出对生存的渴望。外貌：黑色短发，破旧黄色外套，脸上有灰尘。\", \"face_prompt\": \"女性，儿童，黑色短发，虚弱的眼神，苍白的脸\"}], \"scenes\": [{\"name\": \"末日后的城市街道\", \"scene_type\": \"exterior\", \"description\": \"倒塌的高楼，废弃的汽车，布满碎石的道路，阴沉的天空，远处有浓烟，光线压抑，环境荒凉。\"}, {\"name\": \"废弃超市的地下室\", \"scene_type\": \"interior\", \"description\": \"货架倒塌，地面满是碎玻璃和杂物，昏暗阴冷，破洞透进微弱阳光，环境破败，充满危险气息。\"}, {\"name\": \"地下室最里面的小房间\", \"scene_type\": \"interior\", \"description\": \"门窗破损，光线昏暗，墙壁布满裂缝，空间狭小，环境封闭，充满未知。\"}], \"props\": [{\"name\": \"透明水瓶\", \"aliases\": [\"水瓶\"], \"prop_type\": \"accessory\", \"visual_prompt\": \"透明材质，旧，瓶身有磨损痕迹，只剩最后一点水，象征着生命的希望。\", \"owner\": \"男主\"}], \"episodes\": [{\"number\": 1, \"title\": \"废墟中的幸存者\", \"content_summary\": \"末日后的第17天，一名男子在废墟中寻找最后的水源。\", \"main_conflict\": \"生存与孤独的对抗。\", \"cliffhanger\": \"他只剩最后一点水，前路未卜。\", \"key_events\": [\"男子在废墟中行走\", \"打开背包拿出水瓶\", \"旁白揭示生存天数\"]}, {\"number\": 2, \"title\": \"地下室的危险\", \"content_summary\": \"男子在地下室发现水源，却遭遇变异怪物的袭击。\", \"main_conflict\": \"人与变异怪物的追逐。\", \"cliffhanger\": \"怪物突然出现，危机四伏。\", \"key_events\": [\"听到水滴声\", \"发现矿泉水\", \"怪物从货架后冲出\", \"男子逃跑\"]}, {\"number\": 3, \"title\": \"水之抉择\", \"content_summary\": \"男子面临是否将水给小女孩的选择，最终发现隐藏的避难所。\", \"main_conflict\": \"生存资源的分配与希望的抉择。\", \"cliffhanger\": \"避难所的灯光亮起，新的希望开始。\", \"key_events\": [\"发现小女孩\", \"递出水瓶\", \"墙壁裂开，避难所出现\"]}], \"model\": \"deepseek-ai/DeepSeek-R1-0528-Qwen3-8B\", \"target_episodes\": 3, \"ingest_settings\": {\"spine_template\": \"drama\", \"art_style_id\": \"as_1033\", \"visual_style\": \"as_1033\", \"narration_style\": \"first_person\", \"ethnicity\": \"Chinese\"}}','[\"解析原文：849 字\", \"规则识别章节：3 章\", \"调用已配置大模型分析角色、场景、道具和剧集规划\", \"分析完成：2 个角色，3 个场景，1 个道具，3 集规划\", \"已转入资产库：2 个角色，3 个场景，1 个道具\"]','2026-09-07T09:50:40.841765+00:00','2026-09-07T09:50:40.841765+00:00'),('ing-e87ee408caa548fd','deepseek-ai/DeepSeek-R1-0528-Qwen3-8B','五岁陈平安在父亲去世后，面对邻里嘲讽与饥饿，怀抱碎瓷碗的陶罐，被推搡跌倒。顾粲母亲的一碗白饭成为他人生转折点，象征着\'一饭之恩\'。','{\"summary\": \"五岁陈平安在父亲去世后，面对邻里嘲讽与饥饿，怀抱碎瓷碗的陶罐，被推搡跌倒。顾粲母亲的一碗白饭成为他人生转折点，象征着\'一饭之恩\'。\", \"characters\": [{\"name\": \"陈平安\", \"aliases\": [\"平安\"], \"role\": \"主角\", \"is_main\": true, \"gender\": \"男\", \"age_group\": \"child\", \"body_type\": \"娇小但挺拔，略显瘦弱\", \"description\": \"沉默寡言，眼神坚定，面对困境不哭不闹。头发微乱，面色苍白，穿着破旧衣衫，手中紧握陶罐。性格坚韧，内心隐忍，对母亲怀有深厚感情。\", \"face_prompt\": \"男性，五岁，黑色短发，大而明亮的眼睛，苍白肤色，小巧鼻梁\"}, {\"name\": \"顾粲\", \"aliases\": [], \"role\": \"少年\", \"is_main\": false, \"gender\": \"男\", \"age_group\": \"youth\", \"body_type\": \"清瘦，眼神温和\", \"description\": \"顾粲是巷中少年，性格善良，见陈平安饥饿，主动给予帮助。他有着关切的眼神，略显苍白的面容，穿着朴素的衣裳。\", \"face_prompt\": \"男性，二十多岁，黑色短发，深邃眼睛，温和肤色，修长脸型\"}], \"scenes\": [{\"name\": \"破屋内\", \"scene_type\": \"interior\", \"description\": \"一间破旧的屋内，陈平安跪在床前，父亲已逝，母亲咳血。窗外传来议论声，气氛压抑。\"}, {\"name\": \"巷口\", \"scene_type\": \"exterior\", \"description\": \"陈平安站在巷口，被众人推搡在地，怀里抱着装碎瓷片的陶罐。周围人声嘈杂，气氛紧张。\"}, {\"name\": \"巷中\", \"scene_type\": \"exterior\", \"description\": \"陈平安倒地，顾粲递来一碗白饭，字幕浮现\'一饭之恩\'，碗沿轻碰石阶。\"}], \"props\": [{\"name\": \"陶罐\", \"aliases\": [\"碎瓷碗\"], \"prop_type\": \"artifact\", \"visual_prompt\": \"一个破损的陶罐，内装碎瓷片，表面有裂纹，颜色暗淡，大小适中，材质粗糙，象征着破碎的过往和希望。\", \"owner\": \"陈平安\"}, {\"name\": \"粗瓷碗\", \"aliases\": [], \"prop_type\": \"accessory\", \"visual_prompt\": \"一个普通的粗瓷碗，碗沿有轻微磕碰痕迹，颜色朴素，大小适中，象征着顾粲母亲的善意。\", \"owner\": \"顾粲\"}], \"episodes\": [{\"number\": 1, \"title\": \"破碎的开始\", \"content_summary\": \"五岁的陈平安在父亲去世后，面对邻里嘲讽与饥饿，怀抱碎瓷碗的陶罐，被推搡跌倒。\", \"main_conflict\": \"陈平安失去亲人，面对邻里嘲讽和饥饿，内心充满无助。\", \"cliffhanger\": \"顾粲母亲的一碗白饭成为他人生转折点，象征着\'一饭之恩\'。\", \"key_events\": [\"陈平安父亲去世，母亲咳血。\", \"邻里搬空家中器物，陈平安被推搡在地。\", \"顾粲母亲给予一碗白饭，字幕浮现\'一饭之恩\'。\"]}], \"model\": \"deepseek-ai/DeepSeek-R1-0528-Qwen3-8B\", \"target_episodes\": 1, \"ingest_settings\": {\"spine_template\": \"drama\", \"art_style_id\": \"as_1033\", \"visual_style\": \"as_1033\", \"narration_style\": \"first_person\", \"ethnicity\": \"Chinese\"}}','[\"解析原文：176 字\", \"规则识别章节：1 章\", \"调用已配置大模型分析角色、场景、道具和剧集规划\", \"分析完成：2 个角色，3 个场景，2 个道具，1 集规划\", \"已转入资产库：2 个角色，3 个场景，2 个道具\"]','2026-09-07T02:59:08.294533+00:00','2026-09-07T02:59:08.294533+00:00');
